def oracle(s):
    n = len(s)
    if n <= 1:
        return 0
    def lower_char(c):
        o = ord(c)
        if 65 <= o <= 90:
            return chr(o + 32)
        return c
    ans = 0
    prev = lower_char(s[0])
    i = 1
    while i < n:
        cur = lower_char(s[i])
        if cur != prev:
            ans += 1
        prev = cur
        i += 1
    return ans

